#include <stdio.h>

int main(void) {
    char s[200];
    int cnt[4][14] = {0};

    scanf("%s", s);

    for (int i = 0; s[i] != '\0'; i += 3) {
        int value = (s[i] - '0') * 10 + (s[i + 1] - '0');
        char suit = s[i + 2];
        int idx;

        if (suit == 'C') idx = 0;
        else if (suit == 'E') idx = 1;
        else if (suit == 'U') idx = 2;
        else idx = 3;

        cnt[idx][value]++;
    }

    for (int idx = 0; idx < 4; idx++) {
        int duplicated = 0;
        int missing = 0;

        for (int v = 1; v <= 13; v++) {
            if (cnt[idx][v] > 1) {
                duplicated = 1;
            } else if (cnt[idx][v] == 0) {
                missing++;
            }
        }

        if (duplicated) {
            printf("erro\n");
        } else {
            printf("%d\n", missing);
        }
    }

    return 0;
}
